/**
 * Rescue of Lot
 * -------------
 * Four eastern kings overrun Sodom and take Lot captive; Abram arms his trained servants and pursues by night, routing the invaders and refusing any spoil. Stage: torchlit desert march, dust and silhouettes, a swift dawn battle north of Damascus; Abram refusing the king of Sodom's offer on a moonlit plain.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: pillar
 * Game beat: Plan a fast night rescue without taking spoil.
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./abraham-kit.js.
 */

import { THREE, createScene, cityGate, house, column, throne, army, pillar, person, birds } from './abraham-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 2546060850, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x776542, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-12, 0, -58], { name: 'city', r: [0, -0.17, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0xa48b5a, trim: 0x5f5135 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x947d52 });
    }
    W.backdrop(city);

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0xa88f5d, { band: 0xa28a5a });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x8c784e });

    /* army: shields and spears in rank */
    army(W, group, 14.5, 23.6, 6, { shields: [0x8c784e, 0x6b5b3b, 0x8a7a2a, 0x3a5a8a] });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x9c8456 });
    W.disc([0, 6, -12], 5, 0xffef9c, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: 0.07, s: 1.17 });

    /* birds: slow circles high above */
    birds(W, group, 8, 55, { y: 26 });

    return W.finish();
}

export default { build };
